package stream

import (
	"path"
	"sort"
	"strconv"
	"strings"
	"time"
)

// timeNow is the package clock, overridable in tests for deterministic token
// expiry. Production uses time.Now.
var timeNow = time.Now

// Packaging states, exactly as the lane persists them in doc["streams"]
// (Interfaces §1). StateNone means no packaging has run for the item.
const (
	StateNone     = "none"
	StatePartial  = "partial"
	StateComplete = "complete"
	StateFailed   = "failed"
)

// Playback modes. ModeHls means a published build (partial or complete) is
// playable at the playlist URL; ModeDirect is the unconditional floor.
const (
	ModeDirect = "direct"
	ModeHls    = "hls"
)

// SectionKindChapter is the only section kind produced in v1 (projected from
// container chapters). SectionKindMarker is reserved for future
// plugin-detected boundaries and MUST NOT be produced (spec: "Sections from
// container chapters").
const (
	SectionKindChapter = "chapter"
	SectionKindMarker  = "marker"
)

// Describe projects one item's stored document into the read-only playback
// descriptor (Interface 3; the GET /playback handler's ONE domain call). Pure:
// the document is read, never written, and the only computed secret is the
// freshly minted play token, returned via the play URL.
//
//   - mode: hls when the stored streams namespace carries a playable build
//     (state partial or complete with its artifact pointer), direct otherwise —
//     every item keeps the direct floor regardless (INV-floor).
//   - state: none | partial | complete | failed, exactly as the lane persisted.
//   - playURL: the /media URL for the mode, carrying a fresh 4 h media token
//     as the query-parameter fallback (the descriptor handler separately sets
//     the cookie-primary delivery).
//   - sections: the stored ffprobe chapters projected to
//     {kind:"chapter", start, end?, title?}, ordered by start. The marker kind
//     is never produced in v1.
//   - voiceovers: the episode document's episode-linked audio sidecars
//     projected to {index, label} in document order (serial-watch-flow D-2) —
//     stored facts only, never a re-probe, never a packaging-state write.
//   - integrity guard (D5): a COMPLETE state additionally runs the read-only
//     ValidateBuild over the nonce the namespace carries; a broken or evicted
//     build answers the direct floor instead of a playlist the player would
//     die on. Partial builds and nonce-less namespaces are exempt — their
//     wire shape is byte-identical to the pre-guard descriptor.
func (s *Service) Describe(itemID string, doc map[string]any) (mode, state, playURL string, sections, voiceovers []map[string]any) {
	s.normalize()
	state = streamState(doc["streams"])
	voiceovers = projectVoiceovers(doc["parsed"])
	token, _ := s.Issue(itemID, timeNow())
	if state == StatePartial || state == StateComplete {
		if playlist := streamPlaylist(doc["streams"]); playlist != "" && s.buildHealthy(itemID, state, doc["streams"]) {
			return ModeHls, state, playlist + "?" + tokenQuery + "=" + token, projectChapters(doc["ffprobe"]), voiceovers
		}
	}
	return ModeDirect, state, mediaPrefix + "/" + itemID + "/original?" + tokenQuery + "=" + token, projectChapters(doc["ffprobe"]), voiceovers
}

// buildHealthy gates the hls answer on the stored build still existing on
// disk (D5): true — hls proceeds as before — for every partial build and for
// any complete namespace without a nonce (byte-identical to the pre-guard
// behavior); for a complete build WITH a nonce it is exactly ValidateBuild's
// verdict. Strictly read-only: the check stats and reads the published
// directory, never a packaging-state write.
func (s *Service) buildHealthy(itemID string, state string, streams any) bool {
	if state != StateComplete {
		return true
	}
	m, ok := streams.(map[string]any)
	if !ok {
		return true
	}
	nonce, _ := m["nonce"].(string)
	if nonce == "" {
		return true
	}
	return s.ValidateBuild(itemID, nonce) == nil
}

// projectVoiceovers projects the episode document's parsed.sidecars into the
// descriptor's read-only voiceovers shape (serial-watch-flow D-2): document
// order, each entry {index, label} — index is the sidecar's document index
// (the same index the sidecar media variant resolves against), the label
// resolved as the language fact when present, else the containing folder
// name, else the file name. Only AUDIO sidecars are voiceovers; subtitle
// sidecars and serial-level sidecars (parsed.series_sidecars) never project.
// An episode with no audio sidecars carries an empty list. Stored facts only —
// never a re-probe, never a write.
func projectVoiceovers(parsed any) []map[string]any {
	out := []map[string]any{}
	p, ok := parsed.(map[string]any)
	if !ok {
		return out
	}
	raw, ok := p["sidecars"].([]any)
	if !ok {
		return out
	}
	for i, c := range raw {
		sc, ok := c.(map[string]any)
		if !ok {
			continue
		}
		if kind, _ := sc["kind"].(string); kind != "audio" {
			continue
		}
		out = append(out, map[string]any{
			"index": i,
			"label": voiceoverLabel(sc),
		})
	}
	return out
}

// voiceoverLabel resolves one voiceover's display label: the language fact
// when present, else the containing folder name, else the file name (D-2).
// Sidecar relative paths are scanner-stamped slash paths; an unreadable
// relative_path degrades to "".
func voiceoverLabel(sc map[string]any) string {
	if lang, _ := sc["language"].(string); strings.TrimSpace(lang) != "" {
		return lang
	}
	rel, _ := sc["relative_path"].(string)
	if dir := path.Dir(rel); dir != "." && dir != "/" && dir != "" {
		return path.Base(dir)
	}
	return path.Base(rel)
}

// streamState reads the packaging state from the stored streams namespace
// (Interfaces §1 — the lane owns the schema; this is the read side). An absent
// or unreadable namespace reads as StateNone.
func streamState(v any) string {
	m, ok := v.(map[string]any)
	if !ok {
		return StateNone
	}
	s, _ := m["state"].(string)
	switch s {
	case StatePartial, StateComplete, StateFailed:
		return s
	}
	return StateNone
}

// streamPlaylist reads the artifact pointer (a /media-relative playlist URL)
// from the stored streams namespace. Empty when absent.
func streamPlaylist(v any) string {
	m, ok := v.(map[string]any)
	if !ok {
		return ""
	}
	p, _ := m["playlist"].(string)
	return p
}

// projectChapters projects the verbatim ffprobe blob's chapters into the
// descriptor's section shape, ordered by start time. Only chapters — the
// marker kind is reserved and never produced (spec: "Sections from container
// chapters"). Unparseable or absent chapters yield an empty list; sections
// project from stored facts, never a re-probe.
func projectChapters(ffprobe any) []map[string]any {
	probe, ok := ffprobe.(map[string]any)
	if !ok {
		return nil
	}
	raw, ok := probe["chapters"].([]any)
	if !ok {
		return nil
	}
	out := make([]map[string]any, 0, len(raw))
	for _, c := range raw {
		ch, ok := c.(map[string]any)
		if !ok {
			continue
		}
		start, ok := chapterTime(ch, "start")
		if !ok {
			continue // a chapter without a usable start cannot be seeked to
		}
		sec := map[string]any{
			"kind":  SectionKindChapter,
			"start": round3(start),
		}
		if end, ok := chapterTime(ch, "end"); ok && end > start {
			sec["end"] = round3(end)
		}
		if title := strings.TrimSpace(chapterTitle(ch)); title != "" {
			sec["title"] = title
		}
		out = append(out, sec)
	}
	sort.SliceStable(out, func(i, j int) bool {
		return out[i]["start"].(float64) < out[j]["start"].(float64)
	})
	return out
}

// chapterTime resolves a chapter boundary in seconds: ffprobe reports both
// *_time ("12.345678", the scaled string) and the raw integer in the chapter's
// time_base. The string form is preferred; the raw form is converted when the
// base is readable. ok is false when neither is usable.
func chapterTime(ch map[string]any, field string) (float64, bool) {
	if v, ok := ch[field+"_time"].(string); ok {
		if f, err := strconv.ParseFloat(strings.TrimSpace(v), 64); err == nil {
			return f, true
		}
	}
	raw, ok := ch[field].(float64)
	if !ok {
		return 0, false
	}
	if num, den, ok := timeBase(ch); ok {
		return raw * num / den, true
	}
	return 0, false
}

// timeBase parses a chapter's "1/1000"-shaped time_base. ok is false when
// absent or malformed (the raw-integer fallback then gives up).
func timeBase(ch map[string]any) (num, den float64, ok bool) {
	tb, _ := ch["time_base"].(string)
	numS, denS, found := strings.Cut(tb, "/")
	n, err1 := strconv.ParseFloat(strings.TrimSpace(numS), 64)
	d, err2 := strconv.ParseFloat(strings.TrimSpace(denS), 64)
	if !found || err1 != nil || err2 != nil || n == 0 || d == 0 {
		return 0, 0, false
	}
	return n, d, true
}

// chapterTitle reads the chapter's title, tolerating absent facts. Real
// `ffprobe -show_chapters` output nests the title under tags.title; the
// top-level "title" is the fallback shape (the section must carry the title
// through either way — spec: chapters become sections with start, end, and
// title carried through).
func chapterTitle(ch map[string]any) string {
	if tags, ok := ch["tags"].(map[string]any); ok {
		if t, ok := tags["title"].(string); ok {
			return t
		}
	}
	t, _ := ch["title"].(string)
	return t
}

// round3 caps the wire precision of section boundaries (milliseconds — far
// below seek granularity, and it keeps the descriptor human-sized).
func round3(f float64) float64 {
	return float64(int64(f*1000+0.5)) / 1000
}
